22	export type ShouldShowLanguagePromptInput = {
23	  /** The runtime's current PWA site's SFCC site id (e.g. `site.sfccSiteId`), or `undefined`. */
24	  readonly sfccSiteId: string | undefined;
25	  /** The current site's own language — a locale id/alias, e.g. `'fr'` or `'en-GB'`. */
26	  readonly currentLanguage: string;
27	  /** `navigator.languages`, most-preferred first, e.g. `['fr-FR', 'en-US']`. */
28	  readonly browserLanguages: readonly string[];
29	  /** The `l` value from `regionPrefCookie.ts`, in epoch **seconds** — `undefined` if never set. */
30	  readonly suppressedAt: number | undefined;
31	  /** The current time, in epoch **seconds** (same unit as `suppressedAt`). */
32	  readonly now: number;
33	};
34	
35	export type ShouldShowLanguagePromptResult =
36	  | { readonly show: true; readonly targetLanguage: string }
37	  | { readonly show: false };
38	
39	/** Lower-cases and takes the primary subtag of a BCP-47-ish tag: `'fr-FR'` -> `'fr'`. */
40	function primarySubtag(languageTag: string): string {
41	  return languageTag.split('-')[0].toLowerCase();
42	}
