62	 */
63	export function shouldShowLanguagePrompt(input: ShouldShowLanguagePromptInput): ShouldShowLanguagePromptResult {
64	  const { sfccSiteId, currentLanguage, browserLanguages, suppressedAt, now } = input;
65	
66	  if (sfccSiteId !== EU_DOMESTIC_SFCC_SITE_ID) {
67	    return { show: false };
68	  }
69	
70	  if (suppressedAt !== undefined) {
71	    const suppressionWindowEnd = suppressedAt + LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY;
72	    if (now < suppressionWindowEnd) {
73	      return { show: false };
74	    }
75	  }
76	
77	  const browserLanguage = browserLanguages[0];
78	  if (!browserLanguage) {
79	    return { show: false };
80	  }
81	
82	  const browserPrimary = primarySubtag(browserLanguage);
83	  if (browserPrimary === primarySubtag(currentLanguage)) {
84	    return { show: false };
85	  }
86	
87	  if (SUPPORTED_EU_LANGUAGES.includes(browserPrimary)) {
88	    return { show: true, targetLanguage: browserPrimary };
89	  }
90	
91	  return { show: false };
92	}
