1	import { getRouterBasePath } from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils';
2	import { getParamsFromPath, removeBasePathFromPath } from '@salesforce/retail-react-app/app/utils/site-utils';
3	
4	/**
5	 * SFCC's own PLP refinement-filter query param. A filter set on one storefront's PLP is
6	 * meaningless carried into a *different* site's URL, so it is dropped by default whenever this
7	 * function builds a cross-site link. A caller can override this via `opts.disallowParams`.
8	 */
9	export const DEFAULT_DISALLOWED_PARAMS: readonly string[] = ['refine'];
10	
11	/**
12	 * Matches the real shape `useMultiSite()` returns (see
13	 * `node_modules/@salesforce/retail-react-app/app/hooks/use-multi-site.js`) — this function must
14	 * stay hook-free itself, so the caller (a real component) passes its own `buildUrl` in, the same
15	 * technique `buildSafeHref` already uses for the identical reason (see
16	 * `overrides/app/utils/safeHref.ts`).
17	 */
18	export type BuildCrossSiteUrl = (path: string, siteRef?: string, localeRef?: string) => string;
19	
20	export type CrossSiteUrlLocation = Pick<Location, 'pathname' | 'search'>;
21	
22	export type CrossSiteUrlOptions = {
23	  /** Overrides `window.location` — what makes this testable without a real browser location. */
24	  readonly location?: CrossSiteUrlLocation;
25	  /** Query params to strip from the rebuilt URL. Defaults to {@link DEFAULT_DISALLOWED_PARAMS}. */
26	  readonly disallowParams?: readonly string[];
27	};
28	
29	/**
30	 * Builds the relative URL for the shopper's current path on a *different* SFCC/PWA site and
31	 * locale — e.g. switching from `/it-eu/product/123` to the equivalent `fr-eu` URL.
32	 *
33	 * The base SFCC `getPathWithLocale` (`app/utils/url.js`) cannot do this: it resolves its target
34	 * locale from the *current* site's own supported-locales list (`getLocaleByReference(site,
35	 * shortCode)`, scoped to that one `site` object), so it can only ever swap locale within one
36	 * site. Zimmermann's four EU-domestic storefronts are separate PWA sites sharing one region —
37	 * switching "language" here means switching site, which needs the target site's alias as an
38	 * input, not a lookup.
39	 *
40	 * Path/search stripping is modelled directly on `getPathWithLocale`'s own logic (strip the base
41	 * path, strip the current site/locale reference from both pathname and search, trim a trailing
42	 * `&`) and reuses its exact helpers rather than reimplementing the site/locale matching by hand
43	 * — hand-rolling that would mean duplicating the configured site alias/id list ourselves.
44	 *
45	 * Unlike `getPathWithLocale`, this function does not resolve the *target* site via
46	 * `getSiteByReference` — the target alias/locale are forwarded to `buildUrl` untouched, the same
47	 * "receives a target identifier and hands it back untouched" contract
48	 * `ZimmCountryLanguageMismatch` uses for its own `onSwitchLanguage`/`onRedirect` props. There is
49	 * nothing to look up: `buildUrl` (the real implementation behind `useMultiSite()`) already
50	 * accepts an arbitrary site/locale reference directly.
51	 *
52	 * @param targetAlias - the destination site's alias, e.g. `'fr-eu'`.
53	 * @param targetLocale - the destination locale id/alias, e.g. `'fr'`.
54	 * @param buildUrl - the real `buildUrl` from `useMultiSite()`, supplied by the caller.
55	 * @param opts.location - overrides `window.location` (for tests, or a non-DOM caller).
56	 * @param opts.disallowParams - query params to drop; defaults to `['refine']`.
57	 * @returns the relative URL on the target site/locale; the caller performs the hard navigation.
58	 */
59	export function crossSiteUrl(
60	  targetAlias: string,
61	  targetLocale: string,
62	  buildUrl: BuildCrossSiteUrl,
63	  opts: CrossSiteUrlOptions = {},
64	): string {
65	  const location = opts.location ?? window.location;
66	  // getParamsFromPath/removeBasePathFromPath ship untyped from the base SFCC package (see
67	  // BuildCrossSiteUrl's own doc comment above for the same situation with useMultiSite) — their
68	  // return values resolve to `any` with no `.d.ts`, so annotate explicitly rather than let that
69	  // taint every downstream template-literal interpolation of siteRef/localeRef/pathname.
70	  const { siteRef, localeRef }: { siteRef?: string; localeRef?: string } = getParamsFromPath(
71	    `${location.pathname}${location.search}`,
72	  );
73	
74	  const basePath = getRouterBasePath();
75	  let pathname: string = removeBasePathFromPath(location.pathname, basePath);
76	  let search = location.search;
77	
78	  if (siteRef) {
79	    pathname = pathname.replace(`/${siteRef}`, '');
80	    search = search.replace(`site=${siteRef}`, '');
81	  }
82	  if (localeRef) {
83	    pathname = pathname.replace(`/${localeRef}`, '');
84	    search = search.replace(`locale=${localeRef}`, '');
85	  }
86	  // Remove a trailing `&` left behind by either replacement above.
87	  search = search.replace(/&$/, '');
88	
89	  // A bare site-root path (e.g. `/it-eu` with no trailing segment) collapses to an empty string
90	  // once its site segment is stripped — normalise that back to `/` rather than handing
91	  // `buildUrl` a malformed empty path.
92	  if (!pathname) {
93	    pathname = '/';
94	  }
95	
96	  const disallowParams = opts.disallowParams ?? DEFAULT_DISALLOWED_PARAMS;
97	  const queryParams = new URLSearchParams(search);
98	  disallowParams.forEach((param) => queryParams.delete(param));
99	  const queryString = Array.from(queryParams).length !== 0 ? `?${queryParams.toString()}` : '';
100	
101	  return buildUrl(`${pathname}${queryString}`, targetAlias, targetLocale);
102	}
103

