 * locale from the *current* site's own supported-locales list (`getLocaleByReference(site,
 * shortCode)`, scoped to that one `site` object), so it can only ever swap locale within one
 * site. Zimmermann's four EU-domestic storefronts are separate PWA sites sharing one region —
 * switching "language" here means switching site, which needs the target site's alias as an
 * input, not a lookup.
 *
 * Path/search stripping is modelled directly on `getPathWithLocale`'s own logic (strip the base
 * path, strip the current site/locale reference from both pathname and search, trim a trailing
 * `&`) and reuses its exact helpers rather than reimplementing the site/locale matching by hand
 * — hand-rolling that would mean duplicating the configured site alias/id list ourselves.
 *
 * Unlike `getPathWithLocale`, this function does not resolve the *target* site via
 * `getSiteByReference` — the target alias/locale are forwarded to `buildUrl` untouched, the same
 * "receives a target identifier and hands it back untouched" contract
 * `ZimmCountryLanguageMismatch` uses for its own `onSwitchLanguage`/`onRedirect` props. There is
 * nothing to look up: `buildUrl` (the real implementation behind `useMultiSite()`) already
 * accepts an arbitrary site/locale reference directly.
 *
 * @param targetAlias - the destination site's alias, e.g. `'fr-eu'`.
 * @param targetLocale - the destination locale id/alias, e.g. `'fr'`.
 * @param buildUrl - the real `buildUrl` from `useMultiSite()`, supplied by the caller.
 * @param opts.location - overrides `window.location` (for tests, or a non-DOM caller).
 * @param opts.disallowParams - query params to drop; defaults to `['refine']`.
 * @returns the relative URL on the target site/locale; the caller performs the hard navigation.
 */
export function crossSiteUrl(
  targetAlias: string,
  targetLocale: string,
  buildUrl: BuildCrossSiteUrl,
  opts: CrossSiteUrlOptions = {},
): string {
  const location = opts.location ?? window.location;
  // getParamsFromPath/removeBasePathFromPath ship untyped from the base SFCC package (see
  // BuildCrossSiteUrl's own doc comment above for the same situation with useMultiSite) — their
  // return values resolve to `any` with no `.d.ts`, so annotate explicitly rather than let that
  // taint every downstream template-literal interpolation of siteRef/localeRef/pathname.
  const { siteRef, localeRef }: { siteRef?: string; localeRef?: string } = getParamsFromPath(
    `${location.pathname}${location.search}`,
  );

  const basePath = getRouterBasePath();
  let pathname: string = removeBasePathFromPath(location.pathname, basePath);
  let search = location.search;

  if (siteRef) {
    pathname = pathname.replace(`/${siteRef}`, '');
    search = search.replace(`site=${siteRef}`, '');
  }
  if (localeRef) {
    pathname = pathname.replace(`/${localeRef}`, '');
    search = search.replace(`locale=${localeRef}`, '');
  }
  // Remove a trailing `&` left behind by either replacement above.
  search = search.replace(/&$/, '');

  // A bare site-root path (e.g. `/it-eu` with no trailing segment) collapses to an empty string
  // once its site segment is stripped — normalise that back to `/` rather than handing
  // `buildUrl` a malformed empty path.
  if (!pathname) {
    pathname = '/';
  }

  const disallowParams = opts.disallowParams ?? DEFAULT_DISALLOWED_PARAMS;
  const queryParams = new URLSearchParams(search);
  disallowParams.forEach((param) => queryParams.delete(param));
  const queryString = Array.from(queryParams).length !== 0 ? `?${queryParams.toString()}` : '';

  return buildUrl(`${pathname}${queryString}`, targetAlias, targetLocale);
}

